print('above .06 total',sum(r[8]>.06 for r in rows),'of',len(rows),'pct',100*sum(r[8]>.06 for r in rows)/len(rows))
print('above .06 internal/external',sum(r[9]>.06 for r in rows),'pct',100*sum(r[9]>.06 for r in rows)/len(rows))
